func:
const now = Date.now();
const timeout = 1000;
const states = context.get("states") || {};
let owner = context.get("owner") || null;

// Le tick décide entre toutes les demandes reçues depuis le cycle précédent.
if (msg.topic !== "tick") {
    const state = msg.payload;
    const topic = /^robots\/([A-Z0-9_-]{1,16})\/state$/.exec(msg.topic);
    if (msg.retain || !topic || !state || topic[1] !== state.id ||
        !["ligne", "approche", "engage", "libere"].includes(state.passage) ||
        !Number.isFinite(state.distance_to_conflict_mm) ||
        state.distance_to_conflict_mm < 0) return null;

    const session = state.simulation_session;
    if (typeof session === "string" && session !== context.get("simulation_session")) {
        // Une nouvelle simulation remplace la précédente. Les EV3 restent réservés.
        for (const [id, previous] of Object.entries(states)) {
            // progress_mm identifie aussi les simulateurs lancés avant cet ajout.
            const legacySim = previous.name === "huit" && Number.isFinite(previous.progress_mm);
            if (typeof previous.simulation_session !== "string" && !legacySim) continue;
            delete states[id];
            if (owner === id) {
                owner = null;
                context.set("owner", null);
            }
        }
        context.set("simulation_session", session);
    }

    states[state.id] = { ...state, received: now };
    context.set("states", states);
    if (state.id === owner && state.passage === "libere") context.set("owner", null);
    return null;
}

const robots = Object.values(states);
const engaged = robots.filter(robot => robot.passage === "engage");
const starting = now - context.get("started") < 1200;
if (!owner && engaged.length === 1) owner = engaged[0].id;
const conflict = engaged.some(robot => robot.id !== owner);

if (!starting && !conflict && !owner) {
    const waiting = robots.filter(robot =>
        robot.passage === "approche" && now - robot.received < timeout);
    waiting.sort((a, b) =>
        a.distance_to_conflict_mm - b.distance_to_conflict_mm || a.id.localeCompare(b.id));
    if (waiting.length) owner = waiting[0].id;
}
context.set("owner", owner);

const staleOwner = owner && now - states[owner].received >= timeout;
const allRed = starting || conflict || staleOwner;
const phase = allRed ? "all_red" : engaged.length ? "occupied" : owner ? "reserved" : "open";
msg.payload = {
    mode: "acces_cooperatif",
    phase,
    green: owner && !allRed ? [owner] : [],
    occupied_by: engaged.length === 1 ? engaged[0].id : null,
    owner,
    reason: starting ? "demarrage" : conflict ? "conflit" : staleOwner ? "robot muet" : null
};
node.status({ fill: allRed ? "red" : owner ? "yellow" : "green", shape: "dot",
    text: phase + (owner ? " · " + owner : "") });
return msg;

initialize:
context.set("states", {});
context.set("owner", null);
context.set("started", Date.now());
context.set("simulation_session", null);
